"""Start-up guard for the navigation and mapping servers (LOCKED - teams do not edit this file).

Nav2's lifecycle manager configures and activates each server with a service call and waits for the
reply without a time limit. On a busy machine the middleware occasionally loses that reply ("failed
to send response to /behavior_server/change_state (timeout)"): the server has done its part, the
manager waits for ever, navigation never becomes active and the rover never moves, although the
mission clock runs. Seen once in about fifteen launches on the organisers' test laptop.

This node watches the servers' lifecycle states. If they are not all active some time after
launch and nothing has changed for a while, it carries out the remaining transitions itself, in
Nav2's order (configure all, then activate all), and says so in the log. It exits once everything
is active. When start-up goes normally it does nothing.
"""
import sys
import time

import rclpy
from lifecycle_msgs.msg import Transition
from lifecycle_msgs.srv import ChangeState, GetState
from rclpy.node import Node

UNCONFIGURED, INACTIVE, ACTIVE = 1, 2, 3


class NavGuard(Node):
    def __init__(self):
        super().__init__('sparkx_nav_guard')
        self.names = list(self.declare_parameter('nodes', ['slam_toolbox', 'controller_server', 'planner_server',
                                                           'behavior_server', 'bt_navigator']).value)
        self.grace = float(self.declare_parameter('grace_s', 25.0).value)      # leave the lifecycle managers alone this long
        self.stall = float(self.declare_parameter('stall_s', 8.0).value)       # ... and while states are still changing
        self.give_up = float(self.declare_parameter('give_up_s', 240.0).value)
        self.get = {n: self.create_client(GetState, f'/{n}/get_state') for n in self.names}
        self.chg = {n: self.create_client(ChangeState, f'/{n}/change_state') for n in self.names}

    def call(self, client, request, timeout=3.0):
        """One service call with a time limit; None when there is no reply (it may have been lost)."""
        if not client.wait_for_service(timeout_sec=1.0):
            return None
        fut = client.call_async(request)
        rclpy.spin_until_future_complete(self, fut, timeout_sec=timeout)
        if not fut.done():
            client.remove_pending_request(fut)
            return None
        return fut.result()

    def state(self, name):
        r = self.call(self.get[name], GetState.Request())
        return r.current_state.id if r is not None else None

    def run(self):
        t0 = time.monotonic()
        last, last_change, acted = None, t0, 0
        while rclpy.ok():
            states = [self.state(n) for n in self.names]
            now = time.monotonic()
            if all(s == ACTIVE for s in states):
                if acted:
                    self.get_logger().warn(f'navigation active after {now - t0:.0f} s; this guard had to make '
                                           f'{acted} lifecycle transition(s) that the lifecycle manager did not complete')
                else:
                    self.get_logger().info(f'navigation active after {now - t0:.0f} s')
                return 0
            if states != last:
                last, last_change = states, now
            if now - t0 > self.give_up:
                self.get_logger().error('navigation did not become active: ' +
                                        ', '.join(f'{n}={s}' for n, s in zip(self.names, states)))
                return 1
            if now - t0 > self.grace and (acted or now - last_change > self.stall):
                # stalled: do the next missing transition ourselves (configure all first, then activate)
                todo = next(((n, Transition.TRANSITION_CONFIGURE, 'configure') for n, s in zip(self.names, states)
                             if s == UNCONFIGURED), None) or \
                       next(((n, Transition.TRANSITION_ACTIVATE, 'activate') for n, s in zip(self.names, states)
                             if s == INACTIVE), None)
                if todo is not None:
                    n, tid, word = todo
                    self.get_logger().warn(f'start-up stalled ({", ".join(f"{a}={b}" for a, b in zip(self.names, states))}): '
                                           f'{word} {n}')
                    req = ChangeState.Request()
                    req.transition.id = tid
                    self.call(self.chg[n], req, timeout=20.0)
                    acted += 1                     # from here on the guard finishes the bring-up without waiting
                    continue
            time.sleep(1.0 if acted else 2.0)
        return 1


def main():
    rclpy.init()
    node = NavGuard()
    try:
        code = node.run()
    except KeyboardInterrupt:
        code = 0
    node.destroy_node()
    if rclpy.ok():
        rclpy.shutdown()
    sys.exit(code)


if __name__ == '__main__':
    main()
